import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    private static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0, length = 0;

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int c = fs.nextInt();

        boolean[] infectedByHuman = new boolean[n + 1];
        for (int i = 0; i < c; i++) {
            fs.nextInt(); // Infecting person
            int count = fs.nextInt();
            for (int j = 0; j < count; j++) {
                infectedByHuman[fs.nextInt()] = true;
            }
        }

        StringBuilder result = new StringBuilder();
        for (int person = 1; person <= n; person++) {
            if (!infectedByHuman[person]) {
                result.append(person).append('\n');
            }
        }
        System.out.print(result);
    }
}
